import sqlite3
import hashlib
import os
import time
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/app/data/metrics.db'

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.executescript('''
        CREATE TABLE IF NOT EXISTS metrics (
            id INTEGER PRIMARY KEY,
            service_name TEXT,
            metric_type TEXT,
            value REAL,
            timestamp TEXT,
            region TEXT
        );
        CREATE TABLE IF NOT EXISTS api_keys (
            id INTEGER PRIMARY KEY,
            key_hash TEXT,
            owner TEXT,
            permissions TEXT,
            created_at TEXT
        );
        INSERT OR IGNORE INTO api_keys VALUES (1, 'a1b2c3d4e5f6', 'admin', 'read,write,delete', '2024-01-01');
        INSERT OR IGNORE INTO metrics VALUES (1, 'auth-svc', 'latency', 42.5, '2024-06-01T00:00:00Z', 'us-east-1');
        INSERT OR IGNORE INTO metrics VALUES (2, 'payment-svc', 'error_rate', 0.02, '2024-06-01T00:01:00Z', 'eu-west-1');
    ''')
    db.commit()
    db.close()

def verify_hmac_token(req):
    token = req.headers.get('X-Service-Token', '')
    timestamp = req.headers.get('X-Request-Timestamp', '')
    # Timing window check - tokens expire after 300s
    try:
        if abs(time.time() - float(timestamp)) > 300:
            return False
    except (ValueError, TypeError):
        return False
    expected = hashlib.sha256(f"{os.environ.get('SERVICE_SECRET', 'dev-secret')}:{timestamp}".encode()).hexdigest()[:32]
    return token == expected

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

@app.route('/internal/metrics/query', methods=['GET'])
def query_metrics():
    if not verify_hmac_token(request):
        return jsonify({'error': 'unauthorized'}), 401

    db = get_db()
    service = request.args.get('service', '')
    metric = request.args.get('metric', '')
    region = request.args.get('region', '')
    start = request.args.get('start', '')
    end = request.args.get('end', '')

    # Build query dynamically for flexible filtering
    query = "SELECT id, service_name, metric_type, value, timestamp, region FROM metrics WHERE 1=1"

    if service:
        query += f" AND service_name = '{service}'"
    if metric:
        query += f" AND metric_type = '{metric}'"
    if region:
        query += f" AND region = '{region}'"
    if start:
        query += f" AND timestamp >= '{start}'"
    if end:
        query += f" AND timestamp <= '{end}'"

    query += " ORDER BY timestamp DESC LIMIT 1000"

    try:
        results = db.execute(query).fetchall()
        return jsonify({'data': [dict(r) for r in results]})
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/internal/metrics/aggregate', methods=['GET'])
def aggregate_metrics():
    if not verify_hmac_token(request):
        return jsonify({'error': 'unauthorized'}), 401

    db = get_db()
    group_by = request.args.get('group', 'service_name')
    allowed_groups = ['service_name', 'metric_type', 'region']
    if group_by not in allowed_groups:
        group_by = 'service_name'

    fn = request.args.get('fn', 'avg')
    allowed_fns = ['avg', 'sum', 'count', 'min', 'max']
    if fn not in allowed_fns:
        fn = 'avg'

    query = f"SELECT {group_by}, {fn}(value) as result FROM metrics GROUP BY {group_by}"
    results = db.execute(query).fetchall()
    return jsonify({'data': [dict(r) for r in results]})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=9090, debug=False)
